import random

def calculate_objective(seq):
    n = len(seq)
    total = 0
    for k in range(1, n):
        ck = 0
        for i in range(n - k):
            ck += seq[i] * seq[i+k]
        total += ck**2
    return total

def hill_climbing(n, max_iterations=1000000):
    seq = [random.choice([-1, 1]) for _ in range(n)]
    current_obj = calculate_objective(seq)

    for _ in range(max_iterations):
        if current_obj <= 96:
            return seq, current_obj

        idx = random.randint(0, n-1)
        seq[idx] *= -1
        new_obj = calculate_objective(seq)

        if new_obj <= current_obj:
            current_obj = new_obj
        else:
            seq[idx] *= -1

    return seq, current_obj

# Try multiple restarts
for _ in range(10):
    seq, obj = hill_climbing(31)
    if obj <= 96:
        print(f"Found: {seq}, {obj}")
        break
    else:
        print(f"Best so far: {obj}")
